def find_body(fp, name, text_cache):
    text = text_cache[fp]
    pat = re.compile(r'(^|[^A-Za-z0-9_])' + re.escape(name) + r'\s*\(')
    for m in pat.finditer(text):
        # skip forward decls/calls: def line shouldn't start with . or be preceded by '=' etc; find '{' before next ';'
        seg = text[m.end():]
        semi = seg.find(';'); brace = seg.find('{')
        if brace != -1 and (semi == -1 or brace < semi):
            start = m.end() + brace
            depth = 0; k = start
            while k < len(text):
                if text[k] == '{': depth += 1
                elif text[k] == '}':
                    depth -= 1
                    if depth == 0: break
